const { execSync } = require('child_process');
const fs = require('fs');

// 1. Pfad aus JSON suchen oder temporär aus Binary schreiben
let inputPath = $json.path || $json.filePath || $json.file;
const outputPath = '/tmp/converted.wav';
const tempInputPath = '/tmp/input_audio_temp';

// Falls kein Pfad im JSON liegt, schreiben wir den Binary-Buffer kurz auf Disk
if (!inputPath && typeof $binary !== 'undefined' && $binary && $binary.data) {
  const binaryData = Buffer.from($binary.data.data, 'base64');
  fs.writeFileSync(tempInputPath, binaryData);
  inputPath = tempInputPath;
}

if (!inputPath) {
  throw new Error("Kein Dateipfad oder Binary-Inhalt im vorherigen Node gefunden!");
}

// 2. FFmpeg-Pfad sicherstellen
let ffmpegBin = 'ffmpeg';
if (fs.existsSync('/usr/bin/ffmpeg')) {
  ffmpegBin = '/usr/bin/ffmpeg';
} else if (fs.existsSync('/usr/local/bin/ffmpeg')) {
  ffmpegBin = '/usr/local/bin/ffmpeg';
} else if (fs.existsSync('/tmp/ffmpeg')) {
  ffmpegBin = '/tmp/ffmpeg';
} else {
  execSync('wget https://johnvansickle.com/ffmpeg/releases/ffmpeg-release-amd64-static.tar.xz -O /tmp/ffmpeg.tar.xz && tar -xf /tmp/ffmpeg.tar.xz -C /tmp/ && cp /tmp/ffmpeg-*-static/ffmpeg /tmp/ffmpeg && chmod +x /tmp/ffmpeg && rm -rf /tmp/ffmpeg*static* /tmp/ffmpeg.tar.xz');
  ffmpegBin = '/tmp/ffmpeg';
}

// Konvertierung ausführen
execSync(`${ffmpegBin} -y -i "${inputPath}" -ar 16000 -ac 1 -c:a pcm_s16le ${outputPath}`);

// 3. Konvertierte WAV-Datei als Binary bereitstellen
const wavBuffer = fs.readFileSync(outputPath);

// Aufräumen in /tmp
if (fs.existsSync(tempInputPath)) fs.unlinkSync(tempInputPath);
if (fs.existsSync(outputPath)) fs.unlinkSync(outputPath);

return [{
  json: {
    converted: true,
    originalPath: inputPath
  },
  binary: {
    data: {
      data: wavBuffer.toString('base64'),
      mimeType: 'audio/wav',
      fileName: 'converted.wav'
    }
  }
}];

const fs = require('fs');
const path = require('path');

const sourceFolder = '/data/boox_sync/inbound';

if (!fs.existsSync(sourceFolder)) {
  // Wenn nicht mal der Ordner existiert, stumm abbrechen
  return [];
}

// Neueste Datei (WAV, MP3 oder M4A) suchen
const files = fs.readdirSync(sourceFolder)
  .filter(f => /\.(wav|mp3|m4a)$/i.test(f))
  .map(f => ({ name: f, time: fs.statSync(path.join(sourceFolder, f)).mtime.getTime() }))
  .sort((a, b) => b.time - a.time);

// Wenn keine Audiodatei im Ordner liegt: Leeres Array zurückgeben
if (files.length === 0) {
  return [];
}

const latestFilePath = path.join(sourceFolder, files[0].name);

return [{
  json: {
    filePath: latestFilePath,
    fileName: files[0].name
  }
}];

const fs = require('fs');
const path = require('path');

// 1. Pfad aus dem Read/Umwandlung-Node abfragen
const sourcePath = $('UmwandlungMp3_Wav').item.json.originalPath 
  || $('Read from disk').item.json.filePath 
  || $('Read from disk').item.json.path;

if (!sourcePath) {
  throw new Error("Kein Ursprungspfad für die Audiodatei gefunden!");
}

// 2. Transkript-Text aus dem Whisper-Output holen
const transcript = $json?.data?.text || $json?.text || $json?.data || "";

// 3. Modulname aus dem Dateinamen filtern (erstes Wort)
const fullFileName = path.basename(sourcePath, path.extname(sourcePath));
const moduleName = fullFileName.split(/[\s_]+/)[0];

// 4. Zielpfad im Modul-Unterordner erstellen
const targetDir = `/data/lectures/${moduleName}/transcripts`;
if (!fs.existsSync(targetDir)) {
  fs.mkdirSync(targetDir, { recursive: true });
}

const txtPath = path.join(targetDir, `${fullFileName}.txt`);

// 5. Transkript abspeichern
fs.writeFileSync(txtPath, transcript, 'utf8');

// Prüfen ob Datei gespeichert wurde
const isSaved = fs.existsSync(txtPath) && fs.statSync(txtPath).size > 0;

return [{
  json: {
    success: isSaved,
    savedTo: txtPath,
    originalAudio: sourcePath
  }
}];

const fs = require('fs');
const path = require('path');

// 1. Ursprünglichen Dateipfad aus den vorherigen Nodes holen
const originalPath = $('Outputtranskript').item.json.originalAudio 
  || $('UmwandlungMp3_Wav').item.json.originalPath 
  || $('Read from disk').item.json.filePath;

if (!originalPath) {
  throw new Error("Kein ursprünglicher Audio-Pfad zum Verschieben gefunden!");
}

// 2. Ziel-Archivordner definieren
const archiveFolder = '/data/archive/audio';

// Ordner erstellen, falls noch nicht vorhanden
if (!fs.existsSync(archiveFolder)) {
  fs.mkdirSync(archiveFolder, { recursive: true });
}

// 3. Datei ins Archiv kopieren und am Quellort löschen
if (fs.existsSync(originalPath)) {
  const fileName = path.basename(originalPath);
  const targetPath = path.join(archiveFolder, fileName);

  // Kopieren über Mount-Grenzen hinweg
  fs.copyFileSync(originalPath, targetPath);

  // Quelldatei aus dem Sync-Ordner löschen -> triggert Löschen auf dem Boox via Syncthing
  fs.unlinkSync(originalPath);

  return [{
    json: {
      success: true,
      archivedTo: targetPath,
      message: "Audio-Datei erfolgreich ins Archiv verschoben."
    }
  }];
} else {
  return [{
    json: {
      success: false,
      message: `Datei unter ${originalPath} existiert nicht mehr.`
    }
  }];
}
